// Simple asteroid escape game using canvas with id "game"
const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');

function resize() {
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;
}
window.addEventListener('resize', resize);
resize();

// Ship definition
const ship = { x: canvas.width / 2, y: canvas.height - 60, w: 40, h: 20, speed: 5 };
let left = false, right = false, up = false, down = false;
window.addEventListener('keydown', e => { if (e.key === 'ArrowLeft') left = true; if (e.key === 'ArrowRight') right = true; if (e.key === 'ArrowUp') up = true; if (e.key === 'ArrowDown') down = true; });
window.addEventListener('keyup', e => { if (e.key === 'ArrowLeft') left = false; if (e.key === 'ArrowRight') right = false; if (e.key === 'ArrowUp') up = false; if (e.key === 'ArrowDown') down = false; });

// Asteroid pool
const asteroids = [];
let asteroidTimer = 0;
const asteroidInterval = 80; // frames
let score = 0;
let gameOver = false;

function spawnAsteroid() {
  const size = Math.random() * 30 + 20;
  asteroids.push({ x: Math.random() * (canvas.width - size), y: -size, w: size, h: size, speed: Math.random() * 2 + 2 });
}

function update() {
  if (gameOver) return;
  // ship movement
  if (left) ship.x -= ship.speed;
  if (right) ship.x += ship.speed;
  if (up) ship.y -= ship.speed;
  if (down) ship.y += ship.speed;
  // keep within bounds
  ship.x = Math.max(0, Math.min(canvas.width - ship.w, ship.x));
  ship.y = Math.max(0, Math.min(canvas.height - ship.h, ship.y));

  // asteroids
  asteroidTimer++;
  if (asteroidTimer > asteroidInterval) { spawnAsteroid(); asteroidTimer = 0; }
  for (let i = asteroids.length - 1; i >= 0; i--) {
    const a = asteroids[i];
    a.y += a.speed;
    // remove off-screen
    if (a.y > canvas.height) { asteroids.splice(i, 1); score++; }
    // collision
    if (a.x < ship.x + ship.w && a.x + a.w > ship.x && a.y < ship.y + ship.h && a.y + a.h > ship.y) {
      gameOver = true;
    }
  }
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  // ship
  ctx.fillStyle = '#0af';
  ctx.fillRect(ship.x, ship.y, ship.w, ship.h);
  // asteroids
  ctx.fillStyle = '#a33';
  asteroids.forEach(a => ctx.fillRect(a.x, a.y, a.w, a.h));
  // score
  ctx.fillStyle = '#fff';
  ctx.font = '20px sans-serif';
  ctx.fillText('Score: ' + score, 10, 30);
  if (gameOver) {
    ctx.fillStyle = 'rgba(0,0,0,0.5)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#fff';
    ctx.textAlign = 'center';
    ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
  }
}

function loop() {
  update();
  draw();
  if (!gameOver) requestAnimationFrame(loop);
}
requestAnimationFrame(loop);
